const lowp vec3 CLOUDS_TOP_POSITION = vec3(0.0f, 10.0f, 0.0f);
const lowp vec3 CLOUDS_BOTTOM_POSITION = vec3(0.0f, 10.0f, 0.0f);

group_uniforms Horizon;
uniform sampler2D horizon: source_color, repeat_disable;

void sky() {
	lowp vec3 background_texture = texture(background, SKY_COORDS).rgb;
	vec4 clouds_top_above_texture = test_plane_texture(clouds_top_above, CLOUDS_MOVEMENT_SPEED * TIME, CLOUDS_TOP_ABOVE_SCALE, true, vec3(EYEDIR.x, -EYEDIR.y, EYEDIR.z), CLOUDS_TOP_ABOVE_POSITION);
	COLOR = mix(background_texture, clouds_top_above_texture.rgb, clouds_top_above_texture.a);

	vec4 clouds_top_texture = test_plane_texture(clouds_top, CLOUDS_MOVEMENT_SPEED * TIME, CLOUDS_TOP_SCALE, true, vec3(EYEDIR.x, -EYEDIR.y, EYEDIR.z), CLOUDS_TOP_POSITION);
	COLOR = mix(COLOR, clouds_top_texture.rgb, clouds_top_texture.a);

	vec4 clouds_bottom_texture = test_plane_texture(clouds_bottom, CLOUDS_MOVEMENT_SPEED * TIME, CLOUDS_BOTTOM_SCALE, true, EYEDIR, CLOUDS_BOTTOM_POSITION);
	COLOR = mix(COLOR, clouds_bottom_texture.rgb, clouds_bottom_texture.a);

	lowp vec4 horizon_texture = texture(horizon, SKY_COORDS);
