```

```glsl
vec4 test_plane_texture(sampler2D plane_texture, vec3 plane_position, float scale, bool tiling, vec3 eye_dir, vec3 camera_position) {
	vec3 cam = camera_position - plane_position;
	vec2 euv = eye_dir.xz / abs( eye_dir.y );
	vec2 cuv = -cam.xz / cam.y;
	float cam_distance = length(cam);
	float absy = abs(normalize(cam).y);
	vec2 tuv = (euv-cuv) * cam_distance * absy / scale;
	return texture(plane_texture, tuv+vec2(0.5));
}
```


